using FluentValidation;using Inventory.Domain;
namespace Inventory.Application;
public record CreateProduct(string Name,string Sku,string Category,decimal Price,int Stock,int ReorderLevel,string Warehouse);
public class CreateProductValidator:AbstractValidator<CreateProduct>{public CreateProductValidator(){RuleFor(x=>x.Name).NotEmpty().MaximumLength(120);RuleFor(x=>x.Sku).NotEmpty().MaximumLength(40);RuleFor(x=>x.Price).GreaterThanOrEqualTo(0);RuleFor(x=>x.Stock).GreaterThanOrEqualTo(0);RuleFor(x=>x.ReorderLevel).GreaterThanOrEqualTo(0);}}
public static class OrderRules{public static void Validate(IReadOnlyCollection<OrderLine> items){if(items.Count==0)throw new InvalidOperationException("An order must contain items.");if(items.Any(x=>string.IsNullOrWhiteSpace(x.ProductId)||x.Quantity<=0))throw new InvalidOperationException("Each order line needs a product and a positive quantity.");}public static decimal CalculateTotal(IEnumerable<OrderLine> items)=>items.Sum(x=>x.Price*x.Quantity);}
public record DashboardDto(int TotalProducts,decimal StockValue,int TotalOrders,decimal Revenue,int LowStockCount,int OutOfStockCount,IReadOnlyList<Product> Products,IReadOnlyList<object> Orders,IReadOnlyList<decimal> Sales,IReadOnlyList<object> Categories,IReadOnlyList<object> Movements);
public interface IInventoryService { Task<Product> CreateProduct(CreateProduct input,CancellationToken ct);Task<Product?> UpdateProduct(string id,CreateProduct input,CancellationToken ct);Task<Product?> AdjustStock(string id,int delta,string type,CancellationToken ct);Task<Order> CreateOrder(string customer,List<OrderLine> items,CancellationToken ct); }
